  { name: '王五', age: 35, describe: '■■■■■■■■■■■■■■■■■■■■■■■■■■' },
  {
    name: '赵六(异步)',
    age: 45,
    describe: '■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■',
    async: true,
