export default () => {
  const [id] = useState(() => Math.random().toString());
  return (
    <>
      <Typography.Title heading={5}>
        直接更新drawer内容，使用CDrawer.ModalTriggerWrapper组件包裹触发器以阻止关闭Drawer
      </Typography.Title>
      {list.map(item => (
        <CDrawer.TriggerWrapper key={item.name}>
          <Link
            onClick={() => {
              const open = () => {
                CDrawer.open({
                  mask: false,
                  title: item.name,
                  width: `50vw`,
