                  ),
                  wrapper: [DemoContainerJustForDemo],
                  getMountContainer: () => document.getElementById(id)!,
                });
              };

              if (item.async) {
                setTimeout(open, 1e3);
              } else {
                open();
              }
            }}
          >
            {item.name}
          </Link>
        </CDrawer.TriggerWrapper>
      ))}
      <div id={id} />
    </>
  );
};

import React, { useState } from 'react';
import { CDrawer, Link } from '@cloud-materials/common';
import { isNumber } from 'lodash-es';
import DemoContainerJustForDemo from '../../CModal/__docs__/DemoContainerJustForDemo';

export default () => {
  const [id] = useState(() => Math.random().toString());
  return (
    <>
      <CDrawer.TriggerWrapper>
        <Link
          onClick={function foo(e: unknown) {
            const depth = isNumber(e) ? e : 1;
            const forceNew = depth > 1;
            const wrapperId = 'cDrawerForceNew';
            let mountContainer = document.getElementById(id)!;

            if (forceNew) {
              mountContainer = document.createElement('div');
              mountContainer.id = `${wrapperId}${depth}`;
              document.getElementById(wrapperId)!.appendChild(mountContainer);
            }

            CDrawer.open({
              mask: false,
              title: `第${depth}层内容`,
              width: `${Math.max(50 - depth * 2, 12)}vw`,
              forceNew,
              content: (
                <>
                  <Link onClick={() => foo(depth + 1)}>打开第{depth + 1}层</Link>
                </>
              ),
              // 以下仅为demo演示必须要的内容
              wrapper: forceNew ? void 0 : [DemoContainerJustForDemo, { id: wrapperId }],
              getPopupContainer: forceNew ? () => mountContainer : void 0,
              getMountContainer: () => mountContainer,
            });
          }}
        >
          打开第1层drawer
        </Link>
      </CDrawer.TriggerWrapper>
      <div id={id} />
    </>
  );
};

